Restore a just-deleted registration from captured recovery data without overwriting an existing namespace. The restore path validates the YAML content and writes only the registration metadata and source YAML; it does not reconstruct deployment pointers, history, rationale, or audit records. type RestoreManifestRequest = { namespace: string; displayName: string; content: string; source: 'user' | 'library' | 'import'; sourceId?: string;
}; type RestoreManifestResult = { message: string; data: { namespace: string; platform: 'windows' | 'linux' | 'mixed' | 'cross-platform' | 'unknown'; };
